def stats(Ps):
    g = {}
    rowc = [[{} for _ in range(4)] for _ in range(4)]  # rowc[p][i]
    colc = [[{} for _ in range(4)] for _ in range(4)]
    for p,P in enumerate(Ps):
        for i in range(4):
            for j in range(4):
                v = P[i][j]
                if v:
                    g[v] = g.get(v,0)+1
                    rowc[p][i][v] = rowc[p][i].get(v,0)+1
                    colc[p][j][v] = colc[p][j].get(v,0)+1
    return g, rowc, colc

def nbhd(P,i,j):
    c = {}
    for di in (-1,0,1):
        for dj in (-1,0,1):
            ii,jj = i+di, j+dj
            if 0<=ii<4 and 0<=jj<4 and P[ii][jj]:
                c[P[ii][jj]] = c.get(P[ii][jj],0)+1
    return c

def rule_predict(Ps, out, scorename, opt, tb, flip_i, flip_j, verbose_wrong=None):
    g,rowc,colc = stats(Ps)
    wrong = 0
    for i in range(4):
        for j in range(4):
            ii = 3-i if flip_i else i
            jj = 3-j if flip_j else j
            cands = []
            for p,P in enumerate(Ps):
                v = P[ii][jj]
                if not v: continue
                n = nbhd(P,ii,jj)
                if scorename=='g': s = g[v]
                elif scorename=='r': s = rowc[p][ii].get(v,0)
                elif scorename=='c': s = colc[p][jj].get(v,0)
                elif scorename=='n': s = n.get(v,0)
                elif scorename=='g+r': s = g[v]+rowc[p][ii].get(v,0)
                elif scorename=='g+c': s = g[v]+colc[p][jj].get(v,0)
                elif scorename=='g+n': s = g[v]+n.get(v,0)
                elif scorename=='r+c': s = rowc[p][ii].get(v,0)+colc[p][jj].get(v,0)
                elif scorename=='r+n': s = rowc[p][ii].get(v,0)+n.get(v,0)
                elif scorename=='c+n': s = colc[p][jj].get(v,0)+n.get(v,0)
                elif scorename=='g+r+c': s = g[v]+rowc[p][ii].get(v,0)+colc[p][jj].get(v,0)
                cands.append((s,p,v))
            if not cands: pred = 0
            else:
                best = min(c[0] for c in cands) if opt=='min' else max(c[0] for c in cands)
                tied = [c for c in cands if c[0]==best]
                if tb=='pmin': pred = min(tied,key=lambda x:x[1])[2]
                elif tb=='pmax': pred = max(tied,key=lambda x:x[1])[2]
                elif tb=='vmin': pred = min(tied,key=lambda x:x[2])[2]
                else: pred = max(tied,key=lambda x:x[2])[2]
            if pred != out[i][j]:
                wrong += 1
                if verbose_wrong is not None: verbose_wrong.append((i,j,pred,out[i][j]))
    return wrong

